"use strict";(self.webpackChunkultimatelearning=self.webpackChunkultimatelearning||[]).push([[308],{6308:e=>{e.exports=JSON.parse('{"topic":{"id":"packages-access-modifiers","title":"Packages & Access Modifiers","overviewSimple":"Imagine a big cupboard with many labeled drawers so you can easily find your items. Java packages are like these drawers \u2014 they organize your code neatly.","overviewTechnical":["Packages group related classes for better structure.","Two types: built-in packages (java.util), and user-defined packages.","Access levels: public, private, protected, default.","Protected allows subclass access even across packages.","Package structure follows folder structure in file system."],"story":"Riya organized her toys into labeled boxes \u2014 cars in one, dolls in another. Now she could find everything easily, just like Java packages organize code.","realWorldAnalogy":"Access modifiers are like access cards in an office \u2014 some open all doors, some only specific ones.","keyPoints":["Packages = folders for code","public = accessible everywhere","private = inside same class only","protected = subclass + same package","default = same package only"],"exampleSimple":"package school;\\npublic class Student {}","exampleTechnical":["package myapp.utils;\\npublic class Logger {\\n    public static void log(String msg) {\\n        System.out.println(msg);\\n    }\\n}","package animals;\\npublic class Animal {\\n    protected String type;\\n}\\n\\npackage animals.domestic;\\nimport animals.Animal;\\npublic class Dog extends Animal {\\n    public void printType() {\\n        System.out.println(type);\\n    }\\n}"],"extraNotes":["Package names follow reverse domain naming (com.company.project).","private members are not inherited.","Use import to access classes from other packages."],"bestPracticesSimple":["Group similar classes together","Use simple folder names"],"bestPracticesAdvanced":["Use proper package naming hierarchy","Minimize public API surface","Encapsulate data with private fields"]}}')}}]);